        'guide.wizard.welcome.title': 'Bienvenido a Actor Empire',
        'guide.wizard.welcome.body': 'Estás construyendo una vida, no solo persiguiendo un papel. Las mejores partidas equilibran carrera, dinero, fama, relaciones, poder de estudio y planificación a largo plazo.',
        'guide.wizard.weeklyLoop.title': 'Tu ciclo semanal',
        'guide.wizard.weeklyLoop.body': 'Cada semana es un rompecabezas de recursos. Gasta energía en actuación, crecimiento social, negocios o vida personal, y luego avanza la edad para ver los resultados.',
        'guide.wizard.career.title': 'Construye primero la carrera',
        'guide.wizard.career.body': 'CastLink, los ensayos, mejores agentes y buenas actuaciones abren la escalera del entretenimiento. Al principio, el trabajo constante y elegir bien los papeles importan más que perseguir solo proyectos enormes.',
        'guide.wizard.stats.title': 'Conoce qué hace cada estadística',
        'guide.wizard.stats.body': 'La fama eleva tu perfil. La reputación mejora la confianza. Los seguidores amplían tu alcance. El dinero te da opciones. Ninguno reemplaza por completo a los demás.',
        'guide.wizard.business.title': 'Los negocios necesitan gestión',
        'guide.wizard.business.body': 'Los negocios no imprimen dinero solos. El precio, el hype, el personal, el stock y la expansión importan.',
        'guide.wizard.studio.title': 'La productora es un juego a largo plazo',
        'guide.wizard.studio.body': 'Tu estudio brilla cuando desarrollas proyectos fuertes, gestionas estrenos y conviertes victorias en una biblioteca. Las grandes recompensas pueden tardar.',
        'guide.wizard.stories.title': 'Las historias conectadas necesitan cuidado',
        'guide.wizard.stories.body': 'Las franquicias y universos son poderosos porque personajes, reparto, secuelas, cruces y memoria del mercado siguen avanzando.',
        'guide.handbook.title': 'Manual',
        'guide.handbook.subtitle': 'Una referencia clara sobre cómo funciona el juego, para qué sirve cada sistema y cuándo conviene prestarle atención.',
        'guide.handbook.gettingStarted.title': 'Primeros pasos',
        'guide.handbook.gettingStarted.p1': 'Tu primer objetivo es crear impulso fiable. Pequeñas victorias en audiciones, actividad social y gestión del dinero suelen superar las apuestas arriesgadas al principio.',
        'guide.handbook.gettingStarted.p2': 'Piensa semana a semana. Cada decisión compite por tiempo y energía, y dispersarte demasiado frena el progreso en todas partes.',
        'guide.handbook.gettingStarted.p3': 'Usa las apps del teléfono a menudo. CastLink hace crecer tu carrera, Equipo gestiona contratos, las redes amplían alcance y la Guía explica el resto.',
        'guide.handbook.stats.title': 'Estadísticas explicadas',
        'guide.handbook.stats.p1': 'La fama es tu perfil público. Te ayuda a ser visto, conseguir oportunidades mayores y mantener relevancia cultural.',
        'guide.handbook.stats.p2': 'La reputación mide qué tan en serio te toma la industria. Una reputación alta sostiene la confianza y mejores resultados a largo plazo.',
        'guide.handbook.stats.p3': 'Los seguidores son tu alcance social. Ayudan con influencia, patrocinios y crecimiento online, pero no pueden sostener solos una carrera de actuación.',
        'guide.handbook.stats.p4': 'El ánimo y la energía determinan cuánto puedes hacer. Una cuenta rica vale menos si tu personaje está agotado o infeliz.',
        'guide.handbook.career.title': 'Flujo de carrera',
        'guide.handbook.career.p1': 'CastLink es el lugar principal para encontrar trabajo. Más talento, preparación, experiencia y representación mejoran la calidad de los papeles por los que puedes competir.',
        'guide.handbook.career.p2': 'La preparación importa. Los ensayos y elegir bien los papeles hacen que las actuaciones sean más consistentes.',
        'guide.handbook.career.p3': 'El inicio construye historial, la mitad construye impulso y el final trata de influencia, elección y legado.',
        'guide.handbook.weeklyLoop.title': 'Ciclo semanal y energía',
        'guide.handbook.weeklyLoop.p1': 'La energía es el combustible semanal. Actuar, moverse en redes, trabajar negocios y acciones personales la consumen.',
        'guide.handbook.weeklyLoop.p2': 'No desperdicies semanas vacías. Si esperas un proyecto, construye fama, relaciones, habilidades o progreso empresarial.',
        'guide.handbook.weeklyLoop.p3': 'Recuperarse tiene valor. A veces restaurar a tu personaje hace que las siguientes semanas sean más fuertes.',
        'guide.handbook.social.title': 'Fama, seguidores y redes',
        'guide.handbook.social.p1': 'Las redes sociales te mantienen visible y pueden apoyar tu carrera más amplia en el entretenimiento.',
        'guide.handbook.social.p2': 'Cada plataforma cumple una función distinta: imagen, alcance, conversación y monetización.',
        'guide.handbook.social.p3': 'Usa las redes con propósito. No cada post necesita perseguir viralidad.',
        'guide.handbook.relationships.title': 'Relaciones y networking',
        'guide.handbook.relationships.p1': 'Las relaciones profesionales pueden cambiar la calidad de las oportunidades que ves.',
        'guide.handbook.relationships.p2': 'Las relaciones personales no son solo decoración. Descuidarlas puede crear drama, mientras vínculos sanos apoyan una vida más fuerte.',
        'guide.handbook.relationships.p3': 'El networking funciona mejor con el tiempo. El esfuerzo repetido suele superar un gesto caro.',
        'guide.handbook.businesses.title': 'Negocios',
        'guide.handbook.businesses.p1': 'Los negocios son motores de ingresos a largo plazo. Algunos son servicios estables, mientras los de producto recompensan la gestión activa.',
        'guide.handbook.businesses.p2': 'Precio, calidad, hype, personal, stock y expansión importan.',
        'guide.handbook.businesses.p3': 'El marketing funciona mejor cuando el producto, la capacidad y la operación ya están sanos.',
        'guide.handbook.productionHouse.title': 'Productora',
        'guide.handbook.productionHouse.p1': 'Piensa por etapas: desarrollo, producción, estreno y vida posterior importan.',
        'guide.handbook.productionHouse.p2': 'No todo proyecto debe apresurarse. Una mejor planificación puede superar sacar todo a la fuerza.',
        'guide.handbook.productionHouse.p3': 'Tu biblioteca importa. Con el tiempo, el estudio gana valor cuando construyes catálogo en vez de depender de un solo éxito.',
        'guide.handbook.developmentLab.title': 'Laboratorio de desarrollo',
        'guide.handbook.developmentLab.p1': 'La Bóveda guarda guiones y conceptos hasta que estés listo para desarrollarlos, venderlos o producirlos.',
        'guide.handbook.developmentLab.p2': 'Concepto es donde defines género, tono, audiencia e identidad de historia.',
        'guide.handbook.developmentLab.p3': 'Mercado es donde puedes comprar o descubrir guiones. Mira formato, género, calidad y cualquier tema conocido o gancho de franquicia.',
